$('#load-model').onclick=loadModel;$('#model-tab').onclick=loadModel;$('#render-tab').onclick=()=>{setMode('render');status('')};$('#reset-view').onclick=()=>{preset();$('#camera-preset').value='front'};$('#camera-preset').onchange=()=>preset($('#camera-preset').value);$('#wireframe').onclick=()=>{const on=$('#wireframe').getAttribute('aria-pressed')!=='true';$('#wireframe').setAttribute('aria-pressed',String(on));model.traverse(o=>{if(o.isMesh)for(const m of Array.isArray(o.material)?o.material:[o.material])if('wireframe'in m)m.wireframe=on});renderDirty=true};$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('#stage').requestFullscreen()}catch{status('Fullscreen is unavailable in this browser.')}};
